<?php
namespace App\Http\Controllers;
use App\Models\Student;
use App\Models\User;
use Illuminate\Http\Request;
use Illuminate\Validation\Rule;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Facades\Storage;
class StudentController extends Controller {
 private function rules($id=null): array { return [
 'student_id'=>['required','string','max:50',Rule::unique('students','student_id')->ignore($id)],'name'=>'required|string|max:150','profile_photo'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:2048',
 'department'=>'required|string|max:100','technology'=>'required|string|max:100','semester'=>'required|string|max:30','shift'=>'nullable|string|max:30','session'=>'nullable|string|max:30','phone'=>'nullable|string|max:30','email'=>['nullable','email','max:150',Rule::unique('students','email')->ignore($id)],'guardian_name'=>'nullable|string|max:150','guardian_phone'=>'nullable|string|max:30','address'=>'nullable|string','joining_date'=>'nullable|date','status'=>'required|in:Active,Inactive,Graduated','portal_password'=>'nullable|string|min:8'
 ]; }
 public function index(Request $request) { $q=Student::query(); foreach(['department','technology','semester','session','shift','status'] as $f) if($request->filled($f)) $q->where($f,$request->$f); if($request->filled('search')) $q->where(fn($x)=>$x->where('student_id','like','%'.$request->search.'%')->orWhere('name','like','%'.$request->search.'%')->orWhere('phone','like','%'.$request->search.'%')); $students=$q->latest()->paginate(15)->withQueryString(); $departments=Student::select('department')->distinct()->orderBy('department')->pluck('department'); $technologies=Student::select('technology')->distinct()->orderBy('technology')->pluck('technology'); $semesters=Student::select('semester')->distinct()->orderBy('semester')->pluck('semester'); return view('students.index',compact('students','departments','technologies','semesters')); }
 public function create(){ return view('students.create',['student'=>new Student]); }
 public function store(Request $request){ $data=$request->validate($this->rules()); if($request->filled('portal_password') && !$request->filled('email')) return back()->withErrors(['email'=>'Student login তৈরি করতে Email দিতে হবে।'])->withInput(); if($request->filled('portal_password') && User::where('email',$request->email)->exists()) return back()->withErrors(['email'=>'এই Email অন্য একটি account-এ ব্যবহার হচ্ছে।'])->withInput(); $photo=$request->file('profile_photo')?->store('student-photos','public'); unset($data['profile_photo'],$data['portal_password']); $data['profile_photo']=$photo; $student=Student::create($data); if($request->filled('portal_password') && $student->email) User::updateOrCreate(['email'=>$student->email],['name'=>$student->name,'password'=>Hash::make($request->portal_password),'role'=>'student','student_id'=>$student->id]); return redirect()->route('students.index')->with('success','শিক্ষার্থীর তথ্য সংরক্ষণ হয়েছে।'); }
 public function show(Student $student){ $student->load(['attendances'=>fn($q)=>$q->latest('attendance_date')->take(10),'payments'=>fn($q)=>$q->latest()]); return view('students.show',compact('student')); }
 public function edit(Student $student){ return view('students.create',compact('student')); }
 public function update(Request $request,Student $student){ $data=$request->validate($this->rules($student->id)); if($request->filled('portal_password') && !$request->filled('email')) return back()->withErrors(['email'=>'Student login তৈরি করতে Email দিতে হবে।'])->withInput(); $existingAccount=$request->filled('email')?User::where('email',$request->email)->first():null; if($request->filled('portal_password') && $existingAccount && ( $existingAccount->role!=='student' || (int)$existingAccount->student_id!==$student->id)) return back()->withErrors(['email'=>'এই Email অন্য একটি account-এ ব্যবহার হচ্ছে।'])->withInput(); if($request->hasFile('profile_photo')) { if($student->profile_photo) Storage::disk('public')->delete($student->profile_photo); $data['profile_photo']=$request->file('profile_photo')->store('student-photos','public'); } else unset($data['profile_photo']); $password=$data['portal_password']??null; unset($data['portal_password']); $oldAccount=User::where('student_id',$student->id)->first(); $student->update($data); if($student->email && $password) User::updateOrCreate(['email'=>$student->email],['name'=>$student->name,'password'=>Hash::make($password),'role'=>'student','student_id'=>$student->id]); elseif($oldAccount && $student->email) $oldAccount->update(['email'=>$student->email,'name'=>$student->name]); return redirect()->route('students.show',$student)->with('success','তথ্য আপডেট হয়েছে।'); }
 public function destroy(Student $student){ if($student->profile_photo) Storage::disk('public')->delete($student->profile_photo); $student->delete(); return redirect()->route('students.index')->with('success','শিক্ষার্থী মুছে ফেলা হয়েছে।'); }
}
